 return '<div class="instance-selector"><label for="instance-search">当前控制</label><input id="instance-search" type="search" aria-label="搜索当前控制角色" placeholder="搜索角色/皮肤" value="'+esc(state.instanceSearch)+'"><select id="control-instance" aria-label="当前控制的桌宠"><option value="" '+(!state.activeInstanceId?'selected':'')+'>新部署（保存后显示）</option>'+rows.map(p=>'<option value="'+esc(p.id)+'" data-search="'+esc([p.id,p.name,p.skin,p.role].join(' '))+'" '+(p.id===state.activeInstanceId?'selected':'')+'>'+esc((favoriteOn('role',p.role)?'★ ':'')+String(p.number).padStart(2,'0')+' · '+p.name+' · '+(p.visible?'显示中':'已隐藏'))+'</option>').join('')+'</select></div>';
