function page(){switch(state.tab){case'role-settings':return persona();case'settings':return settings();case'resources':return resources();case'resource-manager':return resourceManager();case'workshop':return workshop();case'appearance':return appearance();case'favorites':return favorites();case'favorite-roles':return favoriteCategory('roles');case'favorite-chats':return favoriteCategory('chats');case'favorite-voices':return favoriteCategory('voices');case'favorite-actions':return favoriteCategory('actions');case'favorite-resources':return favoriteCategory('resources');case'overview':return overview();case'fun':return fun();case'chat':return chat();case'character':return character();case'actions':return actions();case'persona':return persona();case'memory':return memory();case'speech':return speech();case'asr':return inputPage(state,{input,area,select,toggle,btn,keyField,esc});case'llm':return llm();case'permissions':return permissions();case'voicechanger':return voiceChanger();case'alerts':return fun();case'voices':return voices();case'bubble':{const b=state.config.ui.bubble;return '<form id="bubble-form" class="card"><h4>聊天气泡DIY</h4><p>文字会自动换行，并按当前桌宠窗口的可见区域重新定位；如果文本高于屏幕可容纳高度，气泡会保留滚动，不再被透明窗口裁掉。桌宠旁的气泡右下角可以直接拖拽调整大小，尺寸会保存到当前角色/实例。</p>'+btn('pick-bubble','选择背景/底框图片')+btn('clear-bubble-image','移除底框图片')+input('background','背景色',b.background,'color')+input('color','文字色',b.color,'color')+input('fontSize','字号',b.fontSize,'number','','min="10" max="28"')+input('minWidth','最小宽度',b.minWidth,'number','','min="120" max="520"')+input('maxWidth','最大宽度',b.maxWidth,'number','','min="120" max="520"')+input('width','当前宽度',b.width,'number','也可以直接拖拽气泡右下角调整。','min="120" max="520"')+input('height','当前高度（0=自动）',b.height,'number','高度为0时按文字自动增长；手动调整后可再次填0恢复自动。','min="0" max="1200"')+input('padding','内留白',b.padding,'number','','min="0" max="30"')+'<button class="primary" type="submit">保存气泡样式</button><p>字幕仍按项目要求只显示中文；背景图会随存档迁移，不会改变角色碰撞范围。</p></form>';}case'saves':return '<div class="card"><h4>存档与换电脑</h4><p>存档包含实例、角色聊天、记忆、导入资源和已经生成的声音，不包含API密钥。软件资源与TTS运行环境在完整应用目录中，换电脑请带完整目录或压缩包，不能只带exe。</p>'+btn('save-create','创建本机存档')+btn('save-export','导出个人存档文件')+btn('save-import','选择存档读入')+'<div id="save-results"></div><p>读档前自动备份；读档关闭电脑操作权限，新机器重新输入密钥。不要公开个人存档。</p></div>';default:return detailedGuideHtml()+'<div class="card"><h4>本机数据与隐私</h4><pre>'+esc(state.dataDir)+'</pre><p>secrets.enc.json仅在此Windows用户DPAPI加密；存档不导出密钥。不公开自己的聊天存档。日志/只读模板和实际验证边界见攻略。</p></div>';}}
