function chat(){const lang=state.config.speech.languageMode;return `<div class="card chat"><div class="chat-role">${rolePicker('chatCharacter','当前角色',state.config.assets.customId||'builtin')}</div><form id="chat-settings-form" class="chat-toolbar"><div><strong>当前语言</strong></div>${select('languageMode','',lang,[['ja','日语'],['zh','中文'],['mixed','中日混合']])}<button type="submit" class="secondary">应用</button></form><div class="chat-toolbar"><span class="badge ${state.config.llm.provider==='mock'?'warning':'ready'}">当前大模型：${esc(state.config.llm.model||'未配置')}${state.config.llm.provider==='mock'?' / 演示':''}</span><span id="reply-state">${esc(state.replyState)}</span></div><div class="toolbar chat-history-tools"><button type="button" class="secondary" data-tab="favorites">查看收藏</button><button type="button" class="secondary" data-tab="permissions">打开白名单应用 / 管理权限</button>${btn('clear-history','清空聊天记录','','danger')}</div><div class="chat-log" role="log">${state.history.filter(t=>!state.starredOnly||t.starred).length?state.history.filter(t=>!state.starredOnly||t.starred).map(turnHtml).join(''):`<div class="chat-empty"><div class="empty-symbol">◌</div><h3>暂无对话</h3><p>选择角色和模型后开始对话。</p></div>`}${state.busy?'<div class="msg pet thinking">正在等待模型回应…</div>':''}</div><div class="chat-attachments"><input id="chat-image-input" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple hidden><button type="button" class="secondary" data-action="pick-chat-images">附加图片</button><span class="fine-print">仅在你启用视觉输入后，随本条消息发送给当前模型；不会写入本机聊天记录。</span><div class="attachment-previews">${state.chatImages.map((image,index)=>`<span class="attachment-chip"><img src="${image.dataUrl}" alt="待发送图片"><button type="button" data-action="remove-chat-image" data-index="${index}" aria-label="移除图片">×</button></span>`).join('')}</div></div><form id="chat-form" class="chat-compose"><input id="chat-input" name="text" placeholder="输入消息…" maxlength="8000" ${state.busy?'disabled':''}><button type="submit" class="primary" ${state.busy?'disabled':''}>发送 ↗</button>${btn('mic',state.micStatus.startsWith('录音')?'结束录音':'♬ 语音输入','aria-label="语音输入"')}${btn('cancel-chat','停止')}</form><div class="mic-meter"><progress id="volume-meter" max="0.2" value="0"></progress><span id="mic-state">${esc(state.micStatus)}</span></div><p id="asr-transcript" class="asr-transcript"></p><label class="switch"><input id="continuous" type="checkbox" ${state.continuous?'checked':''}>本次会话按设置在回复后继续录音（切页或停止即关闭）</label></div>`;}
function historyButtons(turn){if(!turn.id)return '';return `<div class="toolbar message-actions">${turn.retracted?'':btn('star-message',turn.starred?'★ 已收藏':'☆ 收藏',`data-id="${esc(turn.id)}" data-starred="${turn.starred?'false':'true'}"`)}${turn.role==='user'&&!turn.retracted?btn('retract-message','撤回',`data-id="${esc(turn.id)}"`):''}${btn('delete-message','删除',`data-id="${esc(turn.id)}"`,'danger')}</div>`;}
function filterFavorites(){const query=state.favoriteSearch[state.tab]||'',rows=[...root.querySelectorAll('.favorites-content .list-row, .favorites-content .msg')],matches=rows.filter(row=>{const b=row.querySelector('[data-favorite-id]');return favoriteSearchMatches(query,row.textContent,b?.dataset.favoriteId,b?.dataset.favoriteRole,row.dataset.turnId);});const pages=Math.max(1,Math.ceil(matches.length/30)),page=Math.max(1,Math.min(pages,state.favoritePages[state.tab]||1));state.favoritePages[state.tab]=page;for(const row of rows)row.hidden=true;for(const row of matches.slice((page-1)*30,page*30))row.hidden=false;const footer=root.querySelector('.favorite-pagination');if(footer)footer.innerHTML=btn('favorite-prev','上一页',page===1?'disabled':'')+'<span>第 '+page+' / '+pages+' 页 · '+matches.length+' 项</span>'+btn('favorite-next','下一页',page===pages?'disabled':'');}

// Updating favorite badges in-place protects unsaved deployment settings and the currently browsed resource role.
function refreshFavoriteChrome(){
 for(const button of root.querySelectorAll('[data-favorite-kind]')){const id=button.hasAttribute('data-role-candidate')?button.closest('.role-picker').querySelector('select').value:button.dataset.favoriteId;button.dataset.favoriteId=id;button.textContent=favoriteOn(button.dataset.favoriteKind,id,button.dataset.favoriteRole||roleKey())?'★ 取消收藏':'☆ 收藏';}
 for(const picker of root.querySelectorAll('.role-picker select')){const value=picker.value;const options=[...picker.options].sort((a,b)=>favoriteRank('role',a.value,roleKey())-favoriteRank('role',b.value,roleKey())||a.value.localeCompare(b.value));picker.replaceChildren(...options);picker.value=value;}
 refreshInstanceChrome();
 if(state.tab==='resources'){const id=state.resourceRole||roleKey();root.querySelector('#resource-rows').innerHTML=resourceRows({...state.config,assets:{...state.config.assets,customId:id==='builtin'?'':id}});}
}
// Selecting an already deployed matching instance reuses the existing API. Otherwise navigate to deployment, never silently play another pet.
async function ensurePlaybackRole(el){
 const role=el.dataset.playRole;if(!role)return true;
 const matching=state.instances.find(p=>p.running&&p.id===state.activeInstanceId&&instanceRole(p)===role)||state.instances.find(p=>p.running&&instanceRole(p)===role);
 if(!matching){if(state.activeInstanceId){await api.selectInstance(null);await load();}await switchChatRole(role);if(el.dataset.action==='voice-play'){render();return true;}state.tab='character';render();notify('该角色还未部署，请先点击显示桌宠，然后再播放收藏动作。','warning');return false;}
 if(matching.id!==state.activeInstanceId){await api.selectInstance(matching.id);await load();render();}
 if(roleKey()!==role)throw Error('角色归属不一致，已阻止播放。');
 if(el.dataset.action==='animate'&&!state.actions.some(a=>a.id===el.dataset.id)){const bundle=state.bundles.find(b=>el.dataset.id.startsWith(b.id+':')&&bundleRoleKey(b)===role);state.tab='character';render();notify('该动作属于'+(bundle?.skin||'其他皮肤')+'，请先部署对应皮肤后播放。','warning');return false;}
 return true;
}

function turnHtml(turn){const attrs=`data-turn-id="${esc(turn.id||'')}"`;if(turn.retracted)return `<div class="msg ${turn.role==='user'?'user':'pet'} retracted" ${attrs}><span>${turn.role==='user'?'这条消息已撤回':'对应回复已移除'}</span>${historyButtons(turn)}</div>`;if(turn.role==='user')return `<div class="msg user" ${attrs}><div class="msg-meta">${esc(state.config.persona.userSelfName)}</div>${esc(turn.text)}${historyButtons(turn)}</div>`;return replyHtml(turn.reply||{textJa:turn.text,textZh:'',source:'history'},turn);}
function replyHtml(r,turn){const candidates=(r.memoryCandidates||[]).filter(m=>m&&typeof m.content==='string');return `<div class="msg pet" ${turn?`data-turn-id="${esc(turn.id)}"`:''}><div class="msg-meta">${esc(state.config.persona.displayName)} · ${r.source==='llm'?'AI':r.source==='generated'?'项目新增语音':r.source==='original'?'日语原声':r.source==='demo'?'演示模板（不是AI）':'历史记录'}</div>${state.config.speech.showText?`<div class="zh">${esc(r.textZh)}</div>`:'<p class="muted">已按你的设置隐藏回复文字。</p>'}${turn?historyButtons(turn):''}${r.requestId?btn('replay-reply','回放已保存的声音',`data-id="${esc(r.requestId)}"`):''}${candidates.map(m=>`<div class="memory-candidate"><span>建议记住：${esc(m.content)}</span>${btn('remember','确认保存',`data-content="${esc(m.content)}" data-type="${esc(m.type||'preference')}"`)}</div>`).join('')}${(r.tools||[]).map(t=>`<div class="tool-request"><strong>电脑请求：${esc(t.action)}</strong><pre>${esc(JSON.stringify(t.args,null,2))}</pre>${t.status?`<span class="badge">${esc(t.status==='success'?'已执行（有回执）':t.status==='cancelled'?'已取消':'执行失败')}</span>`:t.expired?'<span class="badge warning">历史请求已过期，需重新请求</span>':t.blocked?`<p class="error-text">已拒绝：${esc(t.reason)}</p>`:btn('confirm-tool','检查并确认这一步',`data-id="${esc(t.id)}"`)}${t.result?`<p>${esc(t.result)}</p>`:''}</div>`).join('')}</div>`;}
function deploymentPool(c){
 // A draft's custom pool belongs to its own selected skin, not to whichever pet happens to be active.
 const b=selected(c),available=state.bundles.filter(x=>b?.customId?x.id===b.id:x.operatorId===b?.operatorId&&x.skin===b?.skin&&x.view!=='背面').flatMap(x=>x.animations.map(a=>({...a,id:x.id+':'+a.name,group:x.group})));
 return poolSelect('deploymentActions','自定义动作',c.behaviour.customActionIds,sortFavoriteItems(selectableActions(available),'action',a=>a.id).map(a=>[a.id,a.group+' · '+a.name]));
}
function character(){const c=state.config,u=c.ui;const skins=[...new Set(state.bundles.filter(b=>c.assets.customId&&!c.assets.customId.startsWith('operator:')?b.customId===c.assets.customId:!b.customId&&b.view!=='背面'&&b.operatorId===(c.assets.customId?.startsWith('operator:')?c.assets.customId.slice(9):'Amiya')).map(x=>x.skin))];const operators=[...new Map(state.bundles.filter(b=>!b.customId&&b.operatorId).map(b=>[b.operatorId,b.skin.split(' · ')[0]])).entries()];const characterOptions=[['builtin','阿米娅 · 默认'],...operators.filter(([id])=>id!=='Amiya').map(([id,name])=>['operator:'+id,name]),...state.bundles.filter(b=>b.customId).map(b=>[b.customId,b.skin])];return `<div class="grid two character-grid">${previewHtml()}<form id="character-form" class="card"><h4>${state.activeInstanceId?'编辑当前桌宠 · 保存仅影响这一只':'新部署 · 保存后显示新增桌宠'}</h4>${rolePicker('characterId','当前角色',c.assets.customId||'builtin')}${select('skin','角色皮肤',u.selectedSkin,skins.map(x=>[x,x]))}${select('group','动作组',c.behaviour.actionGroup==='自定义'?'自定义':c.assets.group,[['基建','基建日常'],['战斗','正面战斗'],['全部','全部动作'],['自定义','自定义选择']])}<div id="deployment-pool" ${c.behaviour.actionGroup==='自定义'?'':'hidden'}>${deploymentPool(c)}</div><div class="grid two"><label class="field"><span>当前角色大小 <output id="scale-value">${Math.round(u.scale*100)}%</output></span><input type="range" name="scale" min="0.4" max="1.7" step="0.05" value="${u.scale}"><small></small></label>${input('maxFps','最大帧率',u.maxFps,'number','','min="15" max="60"')}${input('bottomMargin','下边界距离（px）',u.bottomMargin,'number','','min="0" max="500"')}${input('opacity','透明度',u.opacity,'number','','min="0.2" max="1" step="0.05"')}</div><h4 class="deployment-subtitle">基础设置</h4>${toggle('alwaysOnTop','保持置顶',u.alwaysOnTop)}${toggle('closePetsWithControl','关闭控制中心窗口时同时关闭桌宠',u.closePetsWithControl)}${toggle('touchBattleAnimations','抚摸时允许播放战斗动画（默认关闭）',u.touchBattleAnimations)}${toggle('edgeWalkEnabled','沿屏幕四边行走（飞檐走壁）',u.edgeWalkEnabled)}${toggle('idleEnabled','启用闲置陪伴：走动与日常动作',u.idleEnabled)}${toggle('idleSpeechEnabled','闲置时偶尔播放已有原声台词',u.idleSpeechEnabled)}<div class="grid two">${input('idleActionSeconds','闲置动作最小间隔（秒）',u.randomMinMs/1000,'number','','min="2" max="300"')}${input('idleActionMaxSeconds','闲置动作最大间隔（秒）',u.randomMaxMs/1000,'number','','min="2" max="540"')}${input('idleSpeechSeconds','闲置台词间隔（秒）',u.idleSpeechIntervalMs/1000,'number','','min="15" max="900"')}</div>${toggle('pauseMovement','暂停自主动作',u.pauseMovement)}${toggle('gravity','桌面重力与落地',u.gravity)}${toggle('windowEdges','站在其他窗口顶部',u.windowEdges)}${toggle('manualMode','手动模式：左右键移动',u.manualMode)}${toggle('clickThrough','空白区域鼠标穿透',u.clickThrough)}${toggle('muted','静音所有语音',u.muted)}${toggle('shadow','角色阴影',u.shadow)}${toggle('autoStart','开机自启动',u.autoStart)}${toggle('reducedMotion','减少界面动态效果',u.reducedMotion)}<div class="toolbar"><button class="primary" type="submit">保存部署</button>${btn('add-pet','增加一只（最多'+MAX_DESKTOP_PETS+'只）')}${btn('show-pet','显示桌宠')}${btn('clear-pets','一键清除桌宠','','danger')}</div></form></div>${instanceRows()}`;}
function instanceRows(){return '<div class="card"><h4>独立桌宠实例 · '+state.instances.length+' 个配置</h4><p>隐藏保留部署；清除不删除聊天、记忆和素材。</p>'+state.instances.map((p,i)=>'<div class="list-row"><div><strong>'+String(i+1).padStart(2,'0')+' · '+esc(p.name)+'</strong><small>'+esc(p.skin)+' · '+Math.round(p.scale*100)+'% · '+(p.visible?'显示中':'已隐藏')+'</small></div><div class="toolbar">'+btn('select-pet',p.id===state.activeInstanceId?'正在控制':'控制这只','data-id="'+esc(p.id)+'"')+btn('visibility-pet',p.visible?'隐藏':'显示','data-id="'+esc(p.id)+'" data-visible="'+(!p.visible)+'"')+btn('remove-pet','清除','data-id="'+esc(p.id)+'"','danger')+'</div></div>').join('')+'</div>';}
