  const p=state.workshopPreflight;
  const persona=state.config.persona||{};
  const voiceChoices=(state.voices||[]).map(v=>[v.id,v.title||v.name||v.id]);
  const rows=state.workshops.length?state.workshops.map(x=>'<div class="list-row"><div class="grow"><strong>'+esc(x.displayName)+'</strong><small>'+esc(x.roleId)+' · '+esc(x.sourceFormat)+' · '+esc(x.targetBundleId)+'</small></div>'+btn('workshop-apply','应用', 'data-id="'+esc(x.id)+'"')+btn('workshop-export','导出','data-id="'+esc(x.id)+'"')+'</div>').join(''):'<p class="fine-print">还没有保存的工作台工程。预检目录后可保存当前角色的动作映射。</p>';
  return '<div class="card"><h4>创意工坊 / 本地角色制作</h4><p>默认走本地Spine流程，不依赖云端或生成式AI。这里先预检格式和能力，再把动作、角色卡、语音绑定保存为角色隔离工程；不会修改 D:\ak、聊天、记忆或密钥。</p><div class="toolbar">'+btn('workshop-inspect','预检本地模型目录','','primary')+btn('workshop-import','导入工作台工程')+'</div>'+(p?'<div id="workshop-preflight" class="notice '+(p.ready?'success':'warning')+'"><strong>'+esc(p.format)+' · '+(p.ready?'必填项齐全':'需要修复必填项')+'</strong><p>'+esc(p.warnings.join('；')||'未发现额外警告')+'</p><pre>'+esc(JSON.stringify({required:p.required,optional:p.optional,capabilities:p.capabilities,skeleton:p.skeleton},null,2))+'</pre></div>':'<div id="workshop-preflight" class="fine-print">未预检。Live2D/Spine4识别结果会显示能力缺口，不会静默当作完整角色。</div>')+'</div><form id="workshop-form" class="card"><h4>动作、角色卡与语音绑定</h4><p>先完成预检，再选择待机、部署、互动和移动动作。角色卡与语音池只对当前角色/皮肤生效；不会改聊天历史、长期记忆或密钥。</p>'+input('displayName','工程名称',state.config.persona.displayName+' 工作台')+select('idle','待机动作','',choices)+select('deployment','部署动作','',choices)+select('interact','互动动作','',choices)+select('move','移动动作','',choices)+'<h4>角色卡</h4><div class="grid two">'+input('profileDisplayName','角色显示名',persona.displayName)+input('addressCn','中文称呼',persona.addressCn||'博士')+input('addressJa','日语称呼',persona.addressJa||'ドクター')+input('role','角色身份',persona.role||'')+'</div>'+area('personality','性格与行为',persona.personality||'')+area('tone','语气',persona.tone||'')+area('speechHabits','说话习惯',persona.speechHabits||'')+'<h4>语音绑定</h4><p class="fine-print">部署语音默认使用当前角色的部署语音；不选择自定义闲置池时保留系统默认闲置语音。</p><div class="grid two">'+select('deploymentVoiceId','部署语音','__deployment__',[['__deployment__','默认部署语音'],...voiceChoices])+poolSelect('idleVoiceIds','闲置语音池',[],voiceChoices)+poolSelect('interactionVoiceIds','互动语音池',[],voiceChoices)+'</div><button type="submit" class="primary">保存本机工程</button></form><div class="card"><h4>我的工作台工程</h4>'+rows+'</div><details class="card"><summary>格式和能力边界</summary><p>Spine 3.8可接入动作池、部署、待机和源石虫追击；缺碰撞/脚线时使用安全默认并标记待配置。Live2D、Spine 4及其他格式当前只做只读预检，不能宣称拥有骨骼动作、部署或追击能力。</p></details>'
