function persona(){const p=state.config.persona;return `<form id="persona-form" class="card"><h4>人设与称呼</h4><p>人设按角色独立保存，编辑不会影响其他角色。</p><div class="grid two">${input('displayName','角色显示名',p.displayName)}${input('userSelfName','你的名字',p.userSelfName)}${input('addressCn','中文称呼',p.addressCn)}${input('addressJa','日语称呼',p.addressJa)}</div>${input('role','身份',p.role)}${area('personality','性格与行为',p.personality)}${area('tone','语气',p.tone)}${area('speechHabits','口头习惯',p.speechHabits)}<p class="fine-print">修改称呼用于新生成的台词；已有原录音中的「ドクター」不会被重新配音。安全权限不受角色卡影响。</p><div class="toolbar"><button type="submit" class="primary">保存人设</button>${btn('reset-persona','恢复当前角色默认人设')}</div></form>`;}
function memory(){return `<div class="card">${toggle('autoChatMemory','自动保存本角色对话事件到长期记忆',state.config.autoChatMemory)}${btn('save-auto-memory','保存自动记忆开关')}<p>自动条目是对话记录，不是核实事实；删除/撤回消息时同步清理。手动确认事实和自动事件可分别删/暂停。</p></div><div class="card"><h4>新增记忆</h4><p>记忆单独存在本机 SQLite 中，跨重启保留。AI 可以建议记忆，但只有你确认后才保存；暂停的记忆不会交给模型。</p><form id="memory-add" class="chat-compose"><input name="content" placeholder="输入需要保存的内容…" maxlength="2000" required><select name="type"><option value="preference">偏好</option><option value="profile">个人资料</option><option value="shared_experience">共同经历</option><option value="task_context">任务</option><option value="relationship">关系</option></select><button type="submit" class="primary">确认保存</button></form></div>${heading('已保存的记忆',`${state.memories.length} 条`)}<div class="list">${state.memories.length?state.memories.map(m=>`<div class="list-row ${m.paused?'paused':''}"><div class="grow">${state.editing===m.id?`<form id="memory-edit" data-id="${m.id}"><textarea name="content" rows="3" maxlength="2000" required>${esc(m.content)}</textarea><div class="toolbar"><button type="submit" class="primary">保存修改</button>${btn('edit-cancel','取消')}</div></form>`:`<strong>${esc(m.content)}</strong><small>${esc(m.type)} · ${new Date(m.updatedAt).toLocaleString('zh-CN')} · ${m.paused?'暂停使用':m.source==='dialogue_auto'?'自动对话事件（未核实事实）':'已确认'}</small>`}</div><div class="row-actions">${btn('edit-memory','编辑',`data-id="${m.id}"`)}${btn('pause-memory',m.paused?'恢复':'暂停',`data-id="${m.id}"`)}${btn('delete-memory','删除',`data-id="${m.id}"`,'danger')}</div></div>`).join(''):'<div class="card muted">暂无记忆。</div>'}</div>`;}
// Capability metadata is endpoint-scoped: switching provider cannot carry a stale vision or token limit claim.
function modelCapabilityFor(base,model){return state.llmCatalog[base]?.find(m=>m.id===model)||modelCapability(model||'未选择',base);}
function modelCapabilityText(base,model){const cap=modelCapabilityFor(base,model);return '模型容量：'+(cap.contextWindow?cap.contextWindow.toLocaleString():'服务商未提供')+' tokens；最大输出：'+(cap.maxOutputTokens?cap.maxOutputTokens.toLocaleString():'未知')+'；识图：'+(cap.vision===true?'支持':cap.vision===false?'不支持':'待确认')+'。下方是软件用量预算，不会自动扩大到模型最大容量。';}
function rememberLlmDraft(f){const key=modelPreferenceKey(f.dataset.modelBase||state.config.llm.baseUrl,f.dataset.modelId||state.config.llm.model);state.config.llm.modelSettings||={};state.config.llm.modelSettings[key]={maxContextTokens:Number(f.elements.maxContextTokens.value),maxOutputTokens:Number(f.elements.maxOutputTokens.value),visionEnabled:f.elements.visionEnabled.checked};}
function applyLlmModel(f){const base=f.elements.baseUrl.value,model=f.elements.model.value;if(!model)return;try{new URL(base);}catch{notify('请填写有效的供应商Base URL；没有改变模型预算或发送请求。','warning');return;}const cap=modelCapabilityFor(base,model),cfg=selectModelSettings(state.config.llm,base,model,cap,state.config.llm.modelSettings);f.elements.maxContextTokens.value=cfg.maxContextTokens;f.elements.maxOutputTokens.value=cfg.maxOutputTokens;f.elements.visionEnabled.checked=cfg.visionEnabled;f.elements.visionEnabled.disabled=cap.vision===false;f.dataset.modelBase=base;f.dataset.modelId=model;const note=f.querySelector('#model-capability');if(note)note.textContent=modelCapabilityText(base,model);}
function refreshModelChoices(f){const base=f.elements.baseUrl.value,model=f.elements.model.value,models=state.llmCatalog[base]?.map(m=>m.id)||[model].filter(Boolean);f.querySelector('#llm-model-options').innerHTML=models.map(m=>'<option value="'+esc(m)+'"></option>').join('');f.elements.modelChoice.innerHTML=[...new Set([model,...models].filter(Boolean))].map(m=>'<option value="'+esc(m)+'">'+esc(m)+'</option>').join('')+'<option value="__manual__">手动输入其他模型ID</option>';f.elements.modelChoice.value=model;}
function llm(){const c=state.config.llm;const models=[...new Set([c.model,...(state.llmCatalog[c.baseUrl]?.map(m=>m.id)||[]),...state.presets.map(p=>p.name===c.providerLabel?p.model:'')].filter(Boolean))];return '<form id="llm-form" class="card"><h4>LLM连接与模型切换</h4><p>先选择服务商，再从已发现模型中选择或手动输入模型 ID。软件会按当前服务商的 Base URL 和已加密 API Key 调用；模型切换不会把密钥写入配置明文。</p><div class="grid two">'+select('providerLabel','服务商',c.providerLabel,[...state.presets.map(p=>[p.name,p.name]),['本地服务','本地 / Ollama / llama.cpp'],['自定义','自定义 OpenAI 兼容服务'],['演示','演示模板（不是 AI）']])+input('model','模型 ID',c.model,'text','可从下方已发现模型中选择，也可以手动填写。','list="llm-model-options"')+'</div>'+select('modelChoice','选择模型',c.model,[...models.map(m=>[m,m]),['__manual__','手动输入其他模型ID']])+'<p id="model-capability" class="fine-print">'+esc(modelCapabilityText(c.baseUrl,c.model))+'</p><datalist id="llm-model-options">'+models.map(m=>'<option value="'+esc(m)+'"></option>').join('')+'</datalist>'+input('baseUrl','Base URL',c.baseUrl,'url','选择供应商后会自动填入建议地址；也可以手动修改。非本地端点仅接受 HTTPS。')+keyField('llmApiKey','API Key',state.flags.llmApiKey)+'<div class="grid two">'+toggle('visionEnabled','启用图片识别（必须确认当前模型支持视觉输入）',c.visionEnabled,'切换模型后请重新确认视觉能力；文本模型不会被伪装成视觉模型。')+input('maxContextTokens','上下文预算',c.maxContextTokens,'number','不同模型上限不同；软件只做本地预算校验，不保证服务商上限。','min="512" max="1048576"')+input('maxOutputTokens','每轮输出上限',c.maxOutputTokens,'number','切换模型后可按模型文档调整；不会静默覆盖自定义值。','min="64" max="32768"')+input('dailyCalls','每天最多请求次数',c.dailyCalls,'number','','min="1" max="10000"')+input('temperature','回答随机度',c.temperature,'number','','min="0" max="2" step="0.05"')+'</div><div class="toolbar"><button type="submit" class="primary">保存LLM设置</button>'+btn('refresh-llm-models','刷新当前供应商模型列表')+btn('detect-config','帮忙识别配置','data-section="llm"')+btn('test-llm','连接测试（只查模型列表，不推理）')+btn('clear-secret','移除密钥','data-key="llmApiKey"','danger')+'</div><p class="fine-print">图片识别会把图片发送给当前服务商，可能消耗服务商输入额度；演示模式不会联网。刷新模型只读取 /models，不发送聊天内容或图片。</p></form>';}

