  if(form.id==='workshop-form'){
    const d=formData(form);const fd=new FormData(form);
    const project=await api.saveWorkshop({displayName:d.displayName,idle:d.idle,deployment:d.deployment,interact:d.interact,move:d.move,profile:{displayName:d.profileDisplayName,addressCn:d.addressCn,addressJa:d.addressJa,role:d.role,personality:d.personality,tone:d.tone,speechHabits:d.speechHabits},voiceBinding:{deploymentVoiceId:d.deploymentVoiceId,idleVoiceIds:fd.getAll('idleVoiceIds').map(String),interactionVoiceIds:fd.getAll('interactionVoiceIds').map(String)}});
    await load();render();notify('已保存本机工作台工程（动作、角色卡和语音绑定）：'+project.displayName,'success');return;
  }
  if(form.id==='speech-output-form'){await persist({speech:{...c.speech,outputMode:d.outputMode,languageMode:d.languageMode,autoLanguageReference:!!d.autoLanguageReference,replyEnabled:!!d.replyEnabled,showText:!!d.showText,subtitlesEnabled:!!d.subtitlesEnabled,showChinese:!!d.showChinese,subtitleSize:Number(d.subtitleSize),gptSovits:{...c.speech.gptSovits,enabled:!!d.sovitsEnabled,installPath:d.installPath,pythonPath:d.pythonPath,apiUrl:d.apiUrl,gptModelPath:d.gptModelPath,sovitsModelPath:d.sovitsModelPath,referenceAudioPath:d.referenceAudioPath,auxReferenceAudioPaths:String(d.auxReferences||'').split(/\r?\n/).filter(Boolean),trainingReferences:c.speech.gptSovits.trainingReferences.map((r,i)=>({...r,text:d['trainingText'+i]??r.text,language:d['trainingLang'+i]??r.language,reviewed:r.needsReview?!!d['trainingReviewed'+i]:r.reviewed})).filter(r=>!r.removed),promptText:d.promptText,promptLanguage:d.promptLanguage,device:d.device,speed:Number(d.speed)},bailian:{...c.speech.bailian,enabled:!!d.bailianEnabled,region:d.region,baseUrl:d.bailianBaseUrl,model:d.bailianModel,voiceId:d.voiceId,language:d.bailianLanguage,dailyCharBudget:Number(d.dailyCharBudget),monthlyCharBudget:Number(d.monthlyCharBudget)}}},{bailianApiKey:d.bailianApiKey});const roleKey=(c.assets.customId||'Amiya').replace(/^operator:/,'')||'Amiya';const oldTraining=c.voiceTraining?.[roleKey]||{schemaVersion:1,roleId:roleKey,displayName:c.persona.displayName,status:'not_started',samples:[],datasetListPath:'',baseGptModelPath:c.speech.gptSovits.gptModelPath||'',baseSovitsModelPath:c.speech.gptSovits.sovitsModelPath||'',trainedGptModelPath:'',trainedSovitsModelPath:'',validation:{status:'not_run',checkedAt:'',notes:[],sampleIds:[]},error:''};const changedTraining=d.trainedGptPath!==oldTraining.trainedGptModelPath||d.trainedSovitsPath!==oldTraining.trainedSovitsModelPath;await persist({voiceTraining:{...c.voiceTraining,[roleKey]:{...oldTraining,displayName:c.persona.displayName,baseGptModelPath:d.gptModelPath||oldTraining.baseGptModelPath||'',baseSovitsModelPath:d.sovitsModelPath||oldTraining.baseSovitsModelPath||'',trainedGptModelPath:d.trainedGptPath||'',trainedSovitsModelPath:d.trainedSovitsPath||'',status:changedTraining&&oldTraining.status==='verified'?'trained_unverified':oldTraining.status,validation:changedTraining?{status:'not_run',checkedAt:'',notes:[],sampleIds:[]}:oldTraining.validation}}});render();notify('声音输出已保存。');return;}
  if(form.id==='workbench-tts-form'){notify('本地合成中…');const r=await api.workbenchSpeech({text:d.workbenchText,language:d.workbenchLanguage,main:d.referenceAudioPath,aux:String(d.auxReferences||'').split(/\r?\n/).filter(Boolean)});document.querySelector('#workbench-audio').src=r.audioUrl;notify('已保存到角色语音库，不是模型训练。','success');return;}
